<script setup lang="ts">
import {ref} from 'vue'
import AppPage from '../AppPage.vue';import AppNavbar from '@/components/AppNavbar.vue';import AppButton from '@/components/AppButton.vue';import BaseCard from '@/components/BaseCard.vue';import Stage1Field from './Stage1Field.vue';import Stage1Status from './Stage1Status.vue';import {useStage1Page} from '../../services/use-stage1-page';import {stage1Service,label} from '../../services/stage1';import type {Data} from '../../services/stage1'
const p=useStage1Page('invitation_accept'),{error,busy,pending}=p,token=ref(''),invitation=ref<Data|null>(null)
async function preview(){invitation.value=null;await p.read(()=>stage1Service.invitationPreview(token.value.trim()),v=>{invitation.value=v})}
async function respond(accept:boolean){await p.write(()=>p.command<Data>('/invitations/'+(accept?'accept':'reject'),{token:token.value.trim(),expectedVersion:invitation.value!.version}),v=>{invitation.value=v;token.value=''})}
function accepted(value:Data){invitation.value=value}
</script>
<template><AppPage secondary><template #navbar><AppNavbar title="接受工作人员邀请" centered show-back/></template><view class="s1-invite stack"><Stage1Status :error="error" :pending="pending" :busy="busy" @recover="p.recover(accepted)" @retry="p.retry(accepted)" @abandon="p.abandon(accepted)"/><BaseCard class="s1-form"><text>请先核对邀请来自可信店铺负责人。接受后仍需负责人确认，不会立即取得经营权限。</text><Stage1Field v-model="token" label="邀请口令" :maximum="100" :disabled="busy||pending" @update:model-value="invitation=null"/><AppButton :disabled="pending||!token.trim()" :loading="busy" @click="preview">查看邀请</AppButton></BaseCard><BaseCard v-if="invitation" class="s1-form"><text class="s1-title">{{invitation.storeName}}</text><text>{{label(invitation.status)}}</text><text>接受截止 {{invitation.expiresAt}}</text><text v-if="invitation.status==='WAIT_OWNER_CONFIRM'">已接受，等待负责人确认。确认后请退出并重新登录取得最新身份。</text><template v-if="invitation.status==='INVITED'"><AppButton :disabled="pending" :loading="busy" @click="respond(true)">接受并等待负责人确认</AppButton><AppButton variant="quiet" :disabled="pending" :loading="busy" @click="respond(false)">拒绝此邀请</AppButton></template></BaseCard></view></AppPage></template>
<style scoped lang="scss">.s1-invite{padding:$space-4 $page-gutter}.s1-form{display:flex;flex-direction:column;gap:$space-4;line-height:1.7;font-size:15px;overflow-wrap:anywhere}.s1-title{font-size:20px;font-weight:700}</style>
